<script setup>
const {user,loadUser,send,busy}=useReiki()
const mode=ref('login'),form=reactive({name:'',email:'',password:''})
async function submit(){if(await send('/api/auth/'+mode.value,form)){form.password='';await loadUser();await refreshNuxtData()}}
async function logout(){if(await send('/api/auth/logout',{})){clearNuxtData();user.value=null;await navigateTo('/profile')}}
</script>
<template><main class="page"><div class="page-heading"><small>فضای شخصی تو</small><h1>{{user?user.name:'خوش آمدی'}}</h1></div><template v-if="!user"><p>برای نگه‌داشتن نوشته‌ها، علاقه‌مندی‌ها و مسیر تمرین وارد شو.</p><div class="row filters"><button class="chip" :aria-pressed="mode==='login'" @click="mode='login'">ورود</button><button class="chip" :aria-pressed="mode==='register'" @click="mode='register'">ساخت حساب</button></div><form class="card" @submit.prevent="submit"><label v-if="mode==='register'" class="field"><span>نام شما</span><input v-model="form.name" class="input" required maxlength="80" autocomplete="name"/></label><label class="field"><span>ایمیل</span><input v-model="form.email" class="input input-ltr" type="email" required autocomplete="email"/></label><label class="field"><span>رمز عبور {{mode==='register'?'(حداقل ۱۲ نویسه)':''}}</span><input v-model="form.password" class="input input-ltr" type="password" required :minlength="mode==='register'?12:1" maxlength="128" :autocomplete="mode==='register'?'new-password':'current-password'"/></label><button class="btn btn-primary btn-block" :disabled="busy">{{busy?'لطفاً صبر کن…':mode==='login'?'ورود به حساب':'ساخت حساب من'}}</button></form><p class="disclaimer">در این پیش‌نمایش، ایمیل تأیید و بازیابی رمز هنوز فعال نیست. از رمز مستقل استفاده کن و فعلاً اطلاعات حساس پزشکی در ژورنال ننویس.</p></template><template v-else><section class="card"><span class="badge" :class="user.roles.includes('premium')?'badge-premium':'badge-free'">{{user.roles.includes('premium')?'عضویت ویژه فعال':'عضویت رایگان'}}</span><p dir="ltr">{{user.email}}</p><NuxtLink to="/premium" class="btn btn-gold">طرح‌های عضویت</NuxtLink></section><div class="section stack"><NuxtLink v-for="[to,label] in [['/my-courses','دوره‌های من'],['/journal','ژورنال خصوصی'],['/library','علاقه‌مندی‌های من'],['/programs','مسیر تمرین و چالش‌ها'],['/purchases','درخواست‌های خرید'] ]" :key="to" :to="to" class="mini-row">{{label}}<span>←</span></NuxtLink><NuxtLink v-if="user.isAdmin" to="/admin" class="mini-row">مدیریت برنامه <span>←</span></NuxtLink></div><button class="btn btn-ghost" :disabled="busy" @click="logout">خروج از حساب</button><p class="disclaimer">ژورنال در پنل مدیر نمایش داده نمی‌شود. این نسخه هنوز رمزنگاری سرتاسری ندارد.</p></template></main></template>
